          scale == other.scale;
}

/// One project in Husk's own folder, as the Home screen shows it: its name,
/// where it is, how long ago it changed, its size and a small picture of how
/// it looked when it was saved (raw RGBA pixels, empty when there is none).
class ProjectCard {
  final String name;
  final String path;
  final BigInt secondsAgo;
  final BigInt bytes;
  final int thumbWidth;
  final int thumbHeight;
  final Uint8List thumbRgba;

  const ProjectCard({
    required this.name,
    required this.path,
    required this.secondsAgo,
    required this.bytes,
    required this.thumbWidth,
    required this.thumbHeight,
    required this.thumbRgba,
  });

  @override
  int get hashCode =>
      name.hashCode ^
      path.hashCode ^
      secondsAgo.hashCode ^
      bytes.hashCode ^
      thumbWidth.hashCode ^
      thumbHeight.hashCode ^
      thumbRgba.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ProjectCard &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          path == other.path &&
          secondsAgo == other.secondsAgo &&
          bytes == other.bytes &&
          thumbWidth == other.thumbWidth &&
          thumbHeight == other.thumbHeight &&
          thumbRgba == other.thumbRgba;
}

/// A recovery copy left by an earlier session: where it is and how many
/// seconds old it is.
class RecoveryInfo {
  final String path;
  final BigInt secondsAgo;

  const RecoveryInfo({required this.path, required this.secondsAgo});

  @override
  int get hashCode => path.hashCode ^ secondsAgo.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is RecoveryInfo &&
          runtimeType == other.runtimeType &&
          path == other.path &&
          secondsAgo == other.secondsAgo;
}

/// A surface under the cursor, as the viewport reads it: which object it
/// belongs to, the point and which way the surface faces there (both in the
/// scene).
class SurfaceSpot {
  final BigInt object;
  final (double, double, double) position;
  final (double, double, double) normal;

  const SurfaceSpot({
    required this.object,
    required this.position,
    required this.normal,
  });

  @override
  int get hashCode => object.hashCode ^ position.hashCode ^ normal.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SurfaceSpot &&
          runtimeType == other.runtimeType &&
          object == other.object &&
          position == other.position &&
          normal == other.normal;
}

/// The scene's world as the Properties panel shows it: the background
/// colour (red, green, blue, each 0 to 1), how strong the soft studio light
/// on surfaces is, and how strong the studio reflections are (each 0 to 2;
/// 1 is the usual look).
class WorldSettings {
  final (double, double, double) background;
  final double ambient;
  final double reflections;

  /// The colour at the top of the background when the gradient is on; the
  /// background colour is then the one at the bottom.
  final (double, double, double) backgroundTop;
  final bool gradient;

  const WorldSettings({
    required this.background,
    required this.ambient,
    required this.reflections,
    required this.backgroundTop,
    required this.gradient,
  });

  @override
  int get hashCode =>
      background.hashCode ^
      ambient.hashCode ^
      reflections.hashCode ^
      backgroundTop.hashCode ^
      gradient.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WorldSettings &&
          runtimeType == other.runtimeType &&
          background == other.background &&
          ambient == other.ambient &&
          reflections == other.reflections &&
          backgroundTop == other.backgroundTop &&
          gradient == other.gradient;
}
